Lời giải triển khai một hệ thống quản lý việc cần làm (Task) sử dụng thư viện `dataclass` để hỗ trợ đầy đủ các tính năng thêm, xem, sửa và xóa. Hệ thống trả về mã lỗi 404 nếu không tìm thấy ID hoặc có lỗi về định dạng dữ liệu.

```python
import requests
from dataclasses import dataclass, field

class Task:
    def __init__(self, title, completed=False):
        self.title = title
        self.completed = completed

    @dataclass
    def status(self):
        return f"PENDING ({self.title})"

    def save(self):
        if self.status() != "PENDING":
            raise ValueError(f"Task {self.title} not completed")
        return True

    def delete(self):
        if self.status() == "PENDING":
            raise ValueError(f"Task {self.title} already completed")
        return True

class API(object):
    def __init__(self, base_url, token):
        self.base_url = base_url
        self.token = token

    def add_task(self, title, completed=False):
        # Giả định request trả về 200
        response = requests.put(f"{self.base_url}/api/tasks/{title}", headers={'Authorization': f"Bearer {self.token}"})
        return response.status_code == 201

    def get_all_tasks(self):
        response = requests.get(f"{self.base_url}/api/tasks")
        return response.json()

    def update_status(self, task_id, new_status):
        try:
            response = requests.put(f"{self.base_url}/api/tasks/{task_id}", headers={'Authorization': f"Bearer {self.token}"})
            return response.status_code == 200
        except requests.exceptions.RequestException as e:
            return f"Failed to update status for task {task_id}: {e}"

class TodoApp(API):
    def __init__(self, base_url, token):
        super().__init__(base_url, token)
        self.tasks = {}

    def get_task_by_id(self, task_id):
        return self.tasks.get(task_id, None)

    def add_task_to_task(self, task_id, title, completed=False):
        task = Task(title, completed)
        self.tasks[task_id] = task
        return task

    def get_all_tasks(self):
        return list(self.tasks.values())

    def update_status(self, task_id, new_status, **kwargs):
        try:
            task = self.get_task_by_id(task_id)
        except KeyError:
            return f"Task ID {task_id} not found", 404

        if new_status == "completed":
            task.completed = True
        elif new_status == "pending":
            task.completed = False

        task.save()
        return f"Task ID {task_id} updated to {new_status}", 200

    def delete_task(self, task_id):
        return self.tasks.pop(task_id, None)

# Helper functions for testing
def create_response(content, status='OK'):
    if status == 'OK': return content
    return {'status': f'FAIL: {content}'}

def test_api():
    api = API("http://localhost:8080", "invalid_auth")
    response = api.add_task("Title 1", completed=True)
    assert response.status_code == 201
    response = api.get_all_tasks()
    assert len(response) == 3
    response = api.update_status("Title 1", "completed")
    response = api.delete_task("Title 1")
    assert response.status_code == 200

if __name__ == "__main__":
    test_api()
```
